parts.openscad_module:
$fn = 128;

teeth         = 20;
belt_pitch    = 2.0;
belt_width    = 6;
bore_d        = 5;
bore_clearance = 0.15;
hub_d         = 12;
hub_w         = 12;
flange_h      = 1.5;
flange_t      = 1.5;

pitch_d   = teeth * belt_pitch / PI;
pulley_od = pitch_d + 1.5;
flange_d  = pulley_od + 2 * flange_h;
total_h   = belt_width + 2 * flange_t;

module gt2_pulley_20t() {
  difference() {
    union() {
      cylinder(h = total_h, d = flange_d, center = true);
      cylinder(h = hub_w, d = hub_d, center = true);
    }
    cylinder(h = belt_width, d = pulley_od, center = true);
    cylinder(h = hub_w + 2, d = bore_d + bore_clearance, center = true, $fn = 64);
    rotate([90, 0, 0])
      cylinder(h = pulley_od + 2, d = 3.2, center = true, $fn = 32);
    for (i = [0 : teeth - 1])
      rotate([0, 0, 360 * i / teeth])
        translate([pitch_d/2, 0, 0])
          cylinder(h = belt_width + 2, r = belt_pitch * 0.3, center = true, $fn = 12);
  }
}

gt2_pulley_20t();
